/* Theme tokens: day is the default; night applies under [data-theme="night"]. */
:root {
  --button-row-accent: #2f6f6a;
  --button-row-accent-strong: #245652;
  --button-row-on-accent: #fbfaf7;
  --button-row-text: #1f2a2e;
  --button-row-text-muted: #5b6a6f;
  --button-row-border: #c9d2d3;
  --button-row-surface: #fbfaf7;
  --button-row-surface-hover: #eef3f2;
  --button-row-focus: #2f6f6a;
  --button-row-disabled-opacity: 0.45;
}

[data-theme="night"] {
  --button-row-accent: #7fb8b1;
  --button-row-accent-strong: #98cbc4;
  --button-row-on-accent: #0f1a1d;
  --button-row-text: #e4ecea;
  --button-row-text-muted: #9fb0ae;
  --button-row-border: #3a4b50;
  --button-row-surface: #17232781;
  --button-row-surface-hover: #1f2d32;
  --button-row-focus: #9ed6cd;
  --button-row-disabled-opacity: 0.4;
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  font-family: inherit;
}

.button-row__button {
  min-height: 44px;
  padding: 0.5rem 1.25rem;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 500;
  line-height: 1.2;
  border-radius: 999px;
  cursor: pointer;
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    color 150ms ease,
    opacity 150ms ease;
}

.button-row__button:focus {
  outline: none;
}

.button-row__button:focus-visible {
  outline: 2px solid var(--button-row-focus);
  outline-offset: 3px;
}

.button-row__button:disabled {
  cursor: not-allowed;
  opacity: var(--button-row-disabled-opacity);
}

/* Primary: filled, the main action. */
.button-row__button--primary {
  background-color: var(--button-row-accent);
  border: 1px solid var(--button-row-accent);
  color: var(--button-row-on-accent);
}

.button-row__button--primary:hover:not(:disabled) {
  background-color: var(--button-row-accent-strong);
  border-color: var(--button-row-accent-strong);
}

/* Secondary: outlined, supporting action. */
.button-row__button--secondary {
  background-color: transparent;
  border: 1px solid var(--button-row-border);
  color: var(--button-row-text);
}

.button-row__button--secondary:hover:not(:disabled) {
  background-color: var(--button-row-surface-hover);
  border-color: var(--button-row-text-muted);
}

/* Quiet: text only, lowest emphasis. */
.button-row__button--quiet {
  background-color: transparent;
  border: 1px solid transparent;
  color: var(--button-row-text-muted);
  padding-inline: 0.75rem;
}

.button-row__button--quiet:hover:not(:disabled) {
  color: var(--button-row-text);
  text-decoration: underline;
  text-underline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__button {
    transition: none;
  }
}
